head.script:
tailwind.config = {
  darkMode: "class",
  theme: {
    extend: {
      colors: {
        "primary": "#141414",
        "background-light": "#f7f7f7",
        "background-dark": "#191919",
      },
      fontFamily: {
        "display": ["Plus Jakarta Sans", "sans-serif"]
      },
      borderRadius: {"DEFAULT": "0.25rem", "lg": "0.5rem", "xl": "0.75rem", "full": "9999px"},
    },
  },
}

body.script:
const isTeamView = ;
const refreshUrl = '';
const startUrl = '';
const completeUrl = '';

const taskAlert = document.getElementById('taskAlert');
let alertedTasks = new Set();

function updateClock() {
    const now = new Date();
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    const clockEl = document.getElementById('currentTime');
    if (clockEl) clockEl.textContent = `${hours}:${minutes}:${seconds}`;
}
updateClock();
setInterval(updateClock, 1000);

function handleStart(taskId) {
    fetch(startUrl, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {task_id: taskId}})
    })
    .then(r => r.json())
    .then(d => { if (d.result && d.result.success) refreshDashboard(); else alert(TRCF_TASK_I18N.error_prefix + ' ' + (d.result ? d.result.message : TRCF_TASK_I18N.unknown_error)); });
}

function handleComplete(taskId) {
    if (!confirm(TRCF_TASK_I18N.confirm_complete)) return;
    fetch(completeUrl, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {task_id: taskId}})
    })
    .then(r => r.json())
    .then(d => { if (d.result && d.result.success) refreshDashboard(); else alert(TRCF_TASK_I18N.error_prefix + ' ' + (d.result ? d.result.message : TRCF_TASK_I18N.unknown_error)); });
}

function renderProgress(total, completed) {
    const percent = total > 0 ? Math.floor(completed * 100 / total) : 0;
    return `
        <section class="bg-white dark:bg-[#202020] p-6 rounded-xl border border-neutral-200 dark:border-neutral-800 shadow-sm">
            <div class="flex flex-col gap-3">
                <div class="flex justify-between items-center">
                    <h3 class="text-lg font-bold text-primary dark:text-white flex items-center gap-2">
                        <span class="material-symbols-outlined text-green-600">check_circle</span>
                        ${isTeamView ? TRCF_TASK_I18N.progress_overall : TRCF_TASK_I18N.progress_today}
                    </h3>
                    <span class="text-sm font-bold text-neutral-500">${percent}%</span>
                </div>
                <div class="h-2.5 w-full bg-neutral-100 dark:bg-neutral-700 rounded-full overflow-hidden">
                    <div class="h-full bg-primary rounded-full transition-all duration-500" style="width: ${percent}%;"></div>
                </div>
                <p class="text-xs text-neutral-400 font-medium text-right">${completed} / ${total} ${TRCF_TASK_I18N.tasks_completed_suffix}</p>
            </div>
        </section>
    `;
}

function renderTask(task) {
    const stateClasses = {
        'pending': 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 border-neutral-200 dark:border-neutral-700',
        'in_progress': 'bg-yellow-50 dark:bg-yellow-900/20 text-yellow-700 dark:text-yellow-500 border-yellow-200 dark:border-yellow-800',
        'done': 'bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-500 border-green-200 dark:border-green-800',
        'overdue': 'bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-500 border-red-200 dark:border-red-800'
    };
    const stateLabels = {
        'pending': TRCF_TASK_I18N.state_pending,
        'in_progress': TRCF_TASK_I18N.state_in_progress,
        'done': TRCF_TASK_I18N.state_done,
        'overdue': TRCF_TASK_I18N.state_overdue
    };

    const now = new Date();
    const currentHour = now.getHours() + now.getMinutes() / 60;
    const diff = task.time_start - currentHour;

    // Pulse starts 5 mins before start time and continues until state is 'done'
    const shouldPulse = (task.state !== 'done' && diff <= 5/60 + 0.01);

    let badge = `<span class="px-2 py-1 rounded ${stateClasses[task.state]} text-xs font-bold border">${stateLabels[task.state]}</span>`;
    if (shouldPulse) {
        const label = diff > 0 ? TRCF_TASK_I18N.upcoming_soon : TRCF_TASK_I18N.urgent_now;
        const colorClass = diff > 0 
            ? "bg-orange-50 dark:bg-orange-900/20 text-orange-700 dark:text-orange-500 border-orange-200 dark:border-orange-800"
            : "bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-500 border-red-200 dark:border-red-800";
        badge = `<span class="px-2 py-1 rounded ${colorClass} text-xs font-bold border">${label}</span>`;
    }

    const pulseClass = shouldPulse ? 'pulse-ring' : '';

    return `
        <div class="group flex flex-col md:flex-row gap-4 bg-white dark:bg-[#202020] p-4 rounded-xl border border-neutral-200 dark:border-neutral-800 hover:border-neutral-300 dark:hover:border-neutral-600 transition-all shadow-sm ${pulseClass}">
            <div class="flex items-start gap-4 flex-1">
                <div class="flex flex-col gap-1 w-full ${task.state === 'done' ? 'opacity-50 transition-opacity' : ''}">
                    <span class="text-xs font-semibold text-blue-600 bg-blue-50 px-2 py-0.5 rounded w-fit mb-1">${task.time_display}</span>
                    <p class="text-base font-bold text-primary dark:text-white leading-tight ${task.state === 'done' ? 'line-through decoration-neutral-400' : ''}">${task.name}</p>
                    ${task.description ? `<p class="text-sm text-neutral-500 dark:text-neutral-400">${task.description}</p>` : ''}
                    <div class="flex flex-wrap gap-2 mt-2">
                        ${badge}
                    </div>
                </div>
            </div>
            <div class="md:w-1/3 flex flex-col justify-center items-end border-l-0 md:border-l border-neutral-100 dark:border-neutral-700 pl-0 md:pl-4 pt-2 md:pt-0">
                <div class="flex items-center gap-2 mt-2 md:mt-0">
                    ${task.state === 'pending' ? `
                        <button onclick="handleStart(${task.id})" class="flex items-center gap-1.5 px-3 py-2 rounded-lg bg-yellow-50 dark:bg-yellow-900/20 text-yellow-700 dark:text-yellow-500 border border-yellow-200 dark:border-yellow-800 hover:bg-yellow-100 transition-colors text-sm font-bold">
                            <span class="material-symbols-outlined text-[18px]">play_arrow</span> ${TRCF_TASK_I18N.btn_start}
                        </button>
                    ` : ''}
                    ${task.state !== 'done' ? `
                        <button onclick="handleComplete(${task.id})" class="flex items-center gap-1.5 px-3 py-2 rounded-lg bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-500 border border-green-200 dark:border-green-800 hover:bg-green-100 transition-colors text-sm font-bold">
                            <span class="material-symbols-outlined text-[18px]">check</span> ${TRCF_TASK_I18N.btn_complete}
                        </button>
                    ` : ''}
                </div>
            </div>
        </div>
    `;
}

function renderEmployee(employee) {
    const sortedTasks = [...employee.tasks].sort((a, b) => {
        if (a.state === 'done' && b.state !== 'done') return 1;
        if (a.state !== 'done' && b.state === 'done') return -1;
        return a.time_start - b.time_start;
    });

    const iconBox = isTeamView ? `
        <div class="w-8 h-8 bg-gradient-to-br from-purple-500 to-pink-500 rounded-full flex items-center justify-center text-white font-bold text-sm">
            ${employee.name.substring(0, 1)}
        </div>
    ` : '';

    return `
        <section class="${isTeamView ? 'mb-4' : ''}">
            ${isTeamView ? `
                <h3 class="text-lg font-bold text-primary dark:text-white mb-3 flex items-center gap-2">
                    ${iconBox}
                    <span>${employee.name}</span>
                    <span class="text-sm text-neutral-500 font-medium">(${employee.tasks.length} ${TRCF_TASK_I18N.tasks_count_suffix})</span>
                </h3>
            ` : ''}
            <div class="flex flex-col gap-3">
                ${sortedTasks.map(task => renderTask(task)).join('')}
            </div>
        </section>
    `;
}

function checkUpcomingTasks(employees) {
    const now = new Date();
    const currentHour = now.getHours() + now.getMinutes() / 60;

    employees.forEach(emp => {
        emp.tasks.forEach(task => {
            const diff = task.time_start - currentHour;
            if (task.state === 'pending' && !alertedTasks.has(task.id)) {
                if (diff <= 5/60 + 0.01 && diff >= -1/60) { 
                    taskAlert.play().catch(e => console.error("Audio play failed:", e));
                    alertedTasks.add(task.id);
                }
            }
        });
    });
}

function refreshDashboard() {
    fetch(refreshUrl, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {}})
    })
    .then(r => r.json())
    .then(d => {
        if (d.result && d.result.success) {
            const container = document.getElementById('tasks-container');
            if (!d.result.employees || d.result.employees.length === 0) {
                container.innerHTML = `
                    <div class="text-center py-16">
                        <span class="material-symbols-outlined text-neutral-300" style="font-size: 4rem;">task_alt</span>
                        <h3 class="text-xl font-semibold text-neutral-600 mt-4">${isTeamView ? TRCF_TASK_I18N.no_tasks_today_team : TRCF_TASK_I18N.no_tasks_today_mine}</h3>
                        <p class="text-neutral-500 mt-2">${isTeamView ? TRCF_TASK_I18N.no_employees_assigned : TRCF_TASK_I18N.no_tasks_assigned_mine}</p>
                    </div>
                `;
                return;
            }

            let html = renderProgress(d.result.total_tasks, d.result.completed_tasks);
            html += d.result.employees.map(emp => renderEmployee(emp)).join('');
            container.innerHTML = html;

            checkUpcomingTasks(d.result.employees);
        }
    });
}

refreshDashboard();
setInterval(refreshDashboard, 30000);
